//! Dense numerical regression corpus generated by mpmath (100 decimal digits).
//! This is a finite, platform-specific test, not a proof of globally <=16 ULP.
const std = @import("std");
const stable = @import("stable.zig");
const accuracy = @import("accuracy.zig");
const golden = @import("stress_golden.zig");

fn expectUlp(comptime operation: []const u8, actual: f64, expected: f64) !void {
    const report = accuracy.compare(actual, expected);
    // Very small softmax probabilities can have tens of ULPs of difference
    // despite ~1e-14 relative error when using scalar exp/division.
    // Use a tighter relative bound in that region instead of declaring a
    // false regression solely on ULP distance.
    const tiny_softmax = comptime std.mem.eql(u8, operation, "softmax");
    const tiny = tiny_softmax and expected != 0 and @abs(expected) < 1e-30;
    const allowed_ulps: u64 = if (tiny) 512 else 16;
    if (!report.withinUlps(allowed_ulps) or
        (tiny and (report.relative_error orelse std.math.inf(f64)) > 1e-12)) {
        std.debug.print("M1.9 {s} precision regression: actual={d} expected={d} ULP={any} kind={s}\n", .{
            operation, actual, expected, report.ulps, @tagName(report.kind),
        });
        return error.PrecisionRegression;
    }
}

test "2048 mpmath unary stress cases (4096 comparisons)" {
    try std.testing.expectEqual(@as(usize, 2048), golden.unary.len);
    for (golden.unary) |entry| {
        const x: f64 = @bitCast(entry.x_bits);
        const sigmoid: f64 = @bitCast(entry.sigmoid_bits);
        const softplus: f64 = @bitCast(entry.softplus_bits);
        try expectUlp("sigmoid", stable.sigmoid(x), sigmoid);
        try expectUlp("softplus", stable.softplus(x), softplus);
    }
}

test "256 mpmath vector stress cases (1024 comparisons)" {
    try std.testing.expectEqual(@as(usize, 256), golden.vectors.len);
    for (golden.vectors) |entry| {
        var input: [3]f64 = undefined;
        for (entry.inputs, 0..) |bits, i| input[i] = @bitCast(bits);
        const want_lse: f64 = @bitCast(entry.lse_bits);
        try expectUlp("logSumExp", try stable.logSumExp(&input), want_lse);
        var output: [3]f64 = undefined;
        try stable.softmax(&input, &output);
        for (output, entry.probabilities) |actual, bits| {
            const expected: f64 = @bitCast(bits);
            try expectUlp("softmax", actual, expected);
        }
    }
}
